/** Haptic events. Null constant means stay silent on purpose. */
enum class NhakoHaptic(private val constant: Int?, private val minApi: Int, private val fallback: Int?) {
    DragStart(HapticFeedbackConstants.DRAG_START, 34, HapticFeedbackConstants.LONG_PRESS),
    ThresholdActivate(HapticFeedbackConstants.GESTURE_THRESHOLD_ACTIVATE, 34, HapticFeedbackConstants.CLOCK_TICK),
    ThresholdDeactivate(HapticFeedbackConstants.GESTURE_THRESHOLD_DEACTIVATE, 34, HapticFeedbackConstants.CLOCK_TICK),
    MagnetSnap(HapticFeedbackConstants.SEGMENT_TICK, 34, HapticFeedbackConstants.CLOCK_TICK),
    Accept(HapticFeedbackConstants.CONFIRM, 30, HapticFeedbackConstants.VIRTUAL_KEY),
    Decline(HapticFeedbackConstants.REJECT, 30, HapticFeedbackConstants.LONG_PRESS),
    TransferDone(HapticFeedbackConstants.CONFIRM, 30, HapticFeedbackConstants.VIRTUAL_KEY),
    TransferFailed(HapticFeedbackConstants.REJECT, 30, HapticFeedbackConstants.LONG_PRESS),
    PairMatched(HapticFeedbackConstants.CONFIRM, 30, HapticFeedbackConstants.VIRTUAL_KEY),
    ToggleOn(HapticFeedbackConstants.TOGGLE_ON, 34, HapticFeedbackConstants.CLOCK_TICK),
    ToggleOff(HapticFeedbackConstants.TOGGLE_OFF, 34, HapticFeedbackConstants.CLOCK_TICK),
    ButtonPress(null, 0, null),
    ProgressTick(null, 0, null);

    fun perform(view: View) {
        val c = if (Build.VERSION.SDK_INT >= minApi) constant else fallback
        if (c != null) view.performHapticFeedback(c)
    }
}
